class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def singlevalued(root):
    def dfs(node):
        if not node:
            return True, 0

        is_left_single, left_count = dfs(node.left)
        is_right_single, right_count = dfs(node.right)

        if is_left_single and is_right_single:
            if (not node.left or node.left.val == node.val) and (not node.right or node.right.val == node.val):
                return True, left_count + right_count + 1

        return False, left_count + right_count

    _, count = dfs(root)
    return count
